const CACHE='farbound-v2.3.4';
const FILES=['./','./index.html','./app.js','./core.mjs','./catalog.mjs','./frontier.mjs','./frontier-views.mjs','./station-robot.mjs','./system-layout.mjs','./station-layout.mjs','./onfoot.mjs','./onfoot-render.mjs','./surface.mjs','./surface-render.mjs','./galaxy-chart.mjs','./pilot-storage.mjs','./engine-audio.mjs','./release.mjs','./atmosphere.mjs','./dynamic-events.mjs','./style.css','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png','./nebula.webp',...['index.html','app.js','core.mjs','style.css','manifest.webmanifest','icon.svg','icon-192.png','icon-512.png','nebula.webp'].map(f=>'./classic/'+f)];

self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(FILES.map(f=>new Request(new URL(f,self.registration.scope),{cache:'reload'})));await self.skipWaiting();})());});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{await self.clients.claim();for(const key of await caches.keys())if(key.startsWith('farbound-')&&key!==CACHE)await caches.delete(key);})());});
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;const path=FILES.find(p=>new URL(p,self.registration.scope).pathname===u.pathname);if(!path)return;event.respondWith((async()=>{const cache=await caches.open(CACHE),cached=await cache.match(new URL(path,self.registration.scope));if(cached)return cached;return fetch(event.request);})());});
self.addEventListener('message',event=>{if(event.data?.type==='CACHE_STATUS')event.waitUntil((async()=>{const cache=await caches.open(CACHE),ready=(await Promise.all(FILES.map(f=>cache.match(new URL(f,self.registration.scope))))).every(Boolean);event.ports[0]?.postMessage({ready,release:'2.3.4'});})());});
